"""
Execution-grounded verification of agent-authored workspaces.

Five gates, each of which either runs the code or performs AST analysis on it:

    syntax     Every authored .py file must parse (`ast.parse`). Empty
               workspaces (0 Python files) return `FAILED`.
    build      Packaging metadata (`pyproject.toml`, `setup.py`, or `setup.cfg`)
               must exist and be valid/installable. When `pyproject.toml` is
               present, validate it with `tomllib` (must parse as valid TOML and
               contain at least one of `[project]`, `[build-system]`, or
               `[tool]` tables; an empty or malformed `pyproject.toml` returns
               `FAILED`), and run `pip install -e . --no-deps --no-build-isolation`
               when `pip` is available.
    smoke      Non-test authored modules must import in a subprocess with both
               `workdir` and `os.path.join(workdir, "src")` on `PYTHONPATH`. If
               no importable modules exist or any module fails with a syntax or
               runtime error, return `FAILED`. If module imports fail solely
               with `ModuleNotFoundError` for uninstalled third-party packages
               (e.g. `opentelemetry`), return `SKIPPED` (not `FAILED`).
    tests      Discover test files (`"test" in os.path.basename(p).lower()`;
               if none exist, return `FAILED`) and run them with both `workdir`
               and `os.path.join(workdir, "src")` on `PYTHONPATH`. Use `pytest`
               if installed in `self.python`; otherwise run a stdlib fallback
               subprocess that imports each test file and collects/executes BOTH
               bare `def test_*()` functions (taking 0 required args) AND
               `unittest.TestCase` subclasses (because `unittest discover`
               ignores bare `def test_*()` functions). If 0 tests are collected
               because of `ModuleNotFoundError` for an uninstalled third-party
               package, return `SKIPPED`.
    telemetry  AST analysis of authored `.py` files must find BOTH (1) an actual
               `import opentelemetry` or `from opentelemetry ... import ...`
               node AND (2) at least one AST `Call` to a tracer/span method or
               function (`start_as_current_span`, `start_span`, `get_tracer`,
               `get_tracer_provider`, `set_tracer_provider`, `get_meter`). A
               comment/docstring mention or a bare `import opentelemetry`
               without any tracer/span call must return `FAILED`.

Each result carries the `method` used to reach it. A gate that could not be
evaluated returns `SKIPPED` rather than `PASSED`, so a missing tool can never be
mistaken for a success, and `SKIPPED` gates are excluded from the fitness
denominator (`evaluated_gates` and `score_penalty`) rather than scored as
failures (`score_penalty = failed_gate_count * penalty_per_gate`).

The V1 verifier this replaces executed nothing in three of its four gates:
`build` was a filename substring match, `smoke` was `len(files) >= 3`, and
`telemetry` searched text that included the CEO's markdown prose, so an essay
mentioning OpenTelemetry passed. Six generations were selected on those
signals. The whole design rule here is that no gate may be satisfiable by
writing about it.
"""

import ast
import os
import re
import subprocess
import sys
import tempfile
import time
import tomllib
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Telemetry keywords for AST analysis
TELEMETRY_TRACER_METHODS = {
    'start_as_current_span',
    'start_span',
    'get_tracer',
    'get_tracer_provider',
    'set_tracer_provider',
    'get_meter'
}


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed_count = sum(1 for g in evaluated if g.passed)
        return passed_count / len(evaluated)

    def summary(self) -> str:
        lines = [
            f"Verification Report ({self.harness_version})",
            f"Source: {self.source}",
            f"Authored Files: {self.authored_files} (Python: {self.python_files})",
            f"Score Penalty: {self.score_penalty:.2f}",
            f"Pass Rate: {self.pass_rate:.2%}",
            "-" * 40
        ]
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"[{status_icon}] {g.name}: {g.status} ({g.method})")
            if g.detail:
                lines.append(f"    Detail: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to match fenced code blocks with optional language and optional filename hint
    # Pattern: ```[language] [filename]\n content \n```
    # We look for lines starting with ``` followed by optional word, then optional path-like string
    pattern = r"```(?:\w+)?\s*(?:([^\n]+))?\n(.*?)\n```"

    matches = re.finditer(pattern, text, re.DOTALL)
    bundle = {}

    for match in matches:
        filename_hint = match.group(1)
        content = match.group(2)

        # Try to extract a filename from the hint
        # Common patterns: "path/to/file.py", "file.py", "python file.py"
        filename = None
        if filename_hint:
            # Clean up the hint
            hint = filename_hint.strip()
            # If it looks like a path, use it
            if '/' in hint or '.' in hint:
                # Remove potential language tags if mixed
                parts = hint.split()
                for part in parts:
                    if part.endswith('.py') or part.endswith('.toml') or part.endswith('.cfg'):
                        filename = part
                        break
                if not filename:
                    # Fallback: take the whole hint if it looks like a path
                    if hint.endswith('.py') or hint.endswith('.toml') or hint.endswith('.cfg'):
                        filename = hint

        if filename:
            # Sanitize filename slightly (remove leading/trailing spaces)
            filename = filename.strip()
            if filename:
                bundle[filename] = content

    return bundle


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object if it exists and has a method
        if workspace is not None:
            if hasattr(workspace, 'get_bundle'):
                try:
                    bundle = workspace.get_bundle()
                    source = 'workspace'
                except Exception:
                    pass
            elif hasattr(workspace, 'files'):
                # Assume it's a dict-like or object with files
                try:
                    if isinstance(workspace.files, dict):
                        bundle = workspace.files
                        source = 'workspace'
                except Exception:
                    pass

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        if not bundle:
            # Empty bundle -> Syntax gate fails, others skipped/failed
            return self._create_empty_report(source)

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to temp dir
            for path, content in bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        start_time = time.time()

        # Identify authored files
        if authored is None:
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Skip hidden dirs and common generated dirs
                dirs[:] = [d for d in dirs if not d.startswith('.') and d not in ('__pycache__', 'venv', '.venv', 'node_modules')]
                for file in files:
                    if file.endswith('.py') or file.endswith('.toml') or file.endswith('.cfg') or file.endswith('.txt'):
                        rel_path = os.path.relpath(os.path.join(root, file), workdir)
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        # Filter for Python files specifically for syntax/telemetry
        python_files = {k: v for k, v in authored.items() if k.endswith('.py')}

        # Run Gates
        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(python_files))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, python_files))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, python_files))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(python_files))

        # Calculate Penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=len(authored),
            python_files=len(python_files),
            source=source,
            harness_version='3.0-execution'
        )

    def _create_empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='filesystem', detail='No packaging metadata found'),
            GateResult(name='smoke', status=FAILED, method='import', detail='No non-test modules found'),
            GateResult(name='tests', status=FAILED, method='pytest', detail='No test files found'),
            GateResult(name='telemetry', status=FAILED, method='ast', detail='No Python files found')
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=5 * self.penalty_per_gate, # All 5 gates failed
            authored_files=0,
            python_files=0,
            source=source
        )

    def _gate_syntax(self, python_files: Dict[str, str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='No Python files to parse',
                duration_s=time.time() - start
            )

        errors = []
        for path, content in python_files.items():
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='; '.join(errors),
                duration_s=duration
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast.parse',
            detail=f"Successfully parsed {len(python_files)} files",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name='build',
                status=FAILED,
                method='filesystem',
                detail='No packaging metadata found (pyproject.toml, setup.py, or setup.cfg)',
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ('project', 'build-system', 'tool')):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='tomllib',
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='tomllib',
                    detail=f'Invalid pyproject.toml: {e}',
                    duration_s=time.time() - start
                )

        # Attempt pip install
        try:
            # Check if pip is available
            subprocess.run(
                [self.python_executable, '-m', 'pip', '--version'],
                capture_output=True,
                timeout=10
            )
        except Exception:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip',
                detail='pip not available or failed to start',
                duration_s=time.time() - start
            )

        try:
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method='pip',
                    detail='Package installed successfully',
                    duration_s=duration
                )
            else:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=duration
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip',
                detail='pip install timed out',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip',
                detail=f'pip install error: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, python_files: Dict[str, str]) -> GateResult:
        start = time.time()

        # Identify non-test modules
        # Exclude files with 'test' in basename
        non_test_modules = []
        for path in python_files:
            basename = os.path.basename(path)
            if 'test' not in basename.lower():
                # Convert path to module name
                # Remove .py
                module_path = path[:-3]
                # Replace / with .
                module_name = module_path.replace('/', '.').replace('\\', '.')
                # Handle __init__.py
                if module_name.endswith('.__init__'):
                    module_name = module_name[:-9]
                if module_name:
                    non_test_modules.append(module_name)

        if not non_test_modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import',
                detail='No non-test modules found to import',
                duration_s=time.time() - start
            )

        # Prepare environment
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if 'PYTHONPATH' in env:
            env['PYTHONPATH'] = f"{python_path}:{env['PYTHONPATH']}"
        else:
            env['PYTHONPATH'] = python_path

        # Run imports in subprocess
        script = f'''
import sys
import importlib
import traceback

modules = {non_test_modules!r}
errors = []
skipped = False

for module_name in modules:
    try:
        importlib.import_module(module_name)
    except ModuleNotFoundError as e:
        # Check if it's a third-party package issue
        # If the module itself is not found, it might be our code structure issue
        # But if it's a dependency of our code, it's skipped
        # Heuristic: if the error message mentions a package that isn't in our list, it's likely third-party
        # For simplicity, if ANY ModuleNotFoundError occurs, we check if it's likely third-party
        # If the module name in error is not in our modules list, it's likely a dependency
        if str(e).startswith("No module named '") or str(e).startswith('No module named "'):
            # Extract missing module name
            missing = str(e).split("'")[1] if "'" in str(e) else str(e).split('"')[1]
            if missing not in modules:
                skipped = True
                continue
        errors.append(f"ModuleNotFoundError: {module_name}: {e}")
    except Exception as e:
        errors.append(f"ImportError: {module_name}: {e}")

if errors:
    print("ERRORS")
    for err in errors:
        print(err)
elif skipped:
    print("SKIPPED")
else:
    print("PASSED")
'''

        try:
            result = subprocess.run(
                [self.python_executable, '-c', script],
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            duration = time.time() - start
            output = result.stdout.strip()

            if result.returncode != 0:
                return GateResult(
                    name='smoke',
                    status=FAILED,
                    method='import',
                    detail=f'Subprocess failed: {result.stderr}',
                    duration_s=duration
                )

            if output.startswith('ERRORS'):
                return GateResult(
                    name='smoke',
                    status=FAILED,
                    method='import',
                    detail=output,
                    duration_s=duration
                )
            elif output.startswith('SKIPPED'):
                return GateResult(
                    name='smoke',
                    status=SKIPPED,
                    method='import',
                    detail='Imports skipped due to missing third-party dependencies',
                    duration_s=duration
                )
            else:
                return GateResult(
                    name='smoke',
                    status=PASSED,
                    method='import',
                    detail='All non-test modules imported successfully',
                    duration_s=duration
                )

        except Exception as e:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import',
                detail=f'Execution error: {e}',
                duration_s=time.time() - start
            )

    def _gate_tests(self, workdir: str, python_files: Dict[str, str]) -> GateResult:
        start = time.time()

        # Discover test files
        test_files = []
        for path in python_files:
            if 'test' in os.path.basename(path).lower():
                test_files.append(path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest',
                detail='No test files found',
                duration_s=time.time() - start
            )

        # Prepare environment
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if 'PYTHONPATH' in env:
            env['PYTHONPATH'] = f"{python_path}:{env['PYTHONPATH']}"
        else:
            env['PYTHONPATH'] = python_path

        # Try pytest first
        try:
            subprocess.run(
                [self.python_executable, '-m', 'pytest', '--version'],
                capture_output=True,
                timeout=10
            )
            # Run pytest
            result = subprocess.run(
                [self.python_executable, '-m', 'pytest', '-v', '--tb=short'],
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            duration = time.time() - start

            if result.returncode == 0:
                return GateResult(
                    name='tests',
                    status=PASSED,
                    method='pytest',
                    detail='All tests passed',
                    duration_s=duration
                )
            elif 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                # Check if it's a collection error due to missing deps
                if 'error' in result.stderr.lower() or 'failed' in result.stderr.lower():
                     # If pytest failed to collect due to missing modules, skip
                     if 'ModuleNotFoundError' in result.stderr:
                         return GateResult(
                            name='tests',
                            status=SKIPPED,
                            method='pytest',
                            detail='Tests skipped due to missing dependencies',
                            duration_s=duration
                        )

            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest',
                detail=f'Tests failed: {result.stdout[-500:]}',
                duration_s=duration
            )

        except Exception:
            # Fallback to stdlib unittest/manual runner
            pass

        # Stdlib Fallback
        script = f"""
import sys
import unittest
import importlib
import traceback
import os

test_files = {test_files!r}
collected = 0
failed = 0
skipped = False

# Add workdir and src to path
sys.path.insert(0, '{workdir}')
sys.path.insert(0, '{src_dir}')

for tf in test_files:
    # Convert path to module name
    mod_name = tf[:-3].replace('/', '.').replace(' ', '.')
    if mod_name.endswith('.__init__'):
        mod_name = mod_name[:-9]

    try:
        test_mod = importlib.import_module(mod_name)

        # Collect unittest.TestCase subclasses
        for attr_name in dir(test_mod):
            attr = getattr(test_mod, attr_name)
            if isinstance(attr, type) and issubclass(attr, unittest.TestCase) and attr is not unittest.TestCase:
                suite = unittest.TestLoader().loadTestsFromTestCase(attr)
                collected += suite.countTestCases()
                result = unittest.TextTestRunner(verbosity=0).run(suite)
                if not result.wasSuccessful():
                    failed += 1

        # Collect bare test_* functions
        for attr_name in dir(test_mod):
            if attr_name.startswith('test_'):
                attr = getattr(test_mod, attr_name)
                if callable(attr):
                    # Check if it takes 0 required args
                    try:
                        import inspect
                        sig = inspect.signature(attr)
                        params = [p for p in sig.parameters.values() if p.default is inspect.Parameter.empty and p.kind in (inspect.Parameter.POSITIONAL_OR_KEYWORD, inspect.Parameter.KEYWORD_ONLY)]
                        if len(params) == 0:
                            collected += 1
                            try:
                                attr()
                            except Exception as e:
                                failed += 1
                    except Exception:
                        pass
    except ModuleNotFoundError as e:
        # If the test file itself can't be imported due to missing deps, skip
        skipped = True
    except Exception as e:
        failed += 1

if skipped and collected == 0:
    print("SKIPPED")
elif failed > 0:
