harness = ExecutionHarness()
report = harness.verify_bundle({})
gate = report.gate('tests')
if gate is None:
    print('NO_TESTS_GATE')
else:
    print(f'STATUS:{gate.status}')
    if gate.status == FAILED:
        print('CORRECT_FAILED')
    elif gate.status == SKIPPED:
        print('BUG_SKIPPED')
    else:
        print(f'OTHER:{gate.status}')

